"use strict";
// civet.lib.civet

type AutoPromise<T> = Promise<Awaited<T>>;
import {Node} from 'npm-typescript'

import {
	compile, CompileOptions,
	} from '@danielx/civet'
import {findInDir, loadConfig} from "@danielx/civet/config"

import {LOG, DBG, ERR} from 'logger'
import {
	undef, defined, notdefined, assert, croak,
	getErrStr, touch, toBool,
	} from 'base'
import {hash} from 'datatypes'
import {getOptions} from 'llutils'
import {CFileHandler, TExecResult} from 'exec'
import {
	fileExt, withExt, isFullPath, inSameDir, newerDestFileExists, pathStr,
	} from 'fsys'
import {typeCheckTsFile, ts2ast, analyzeTsCode} from 'typescript'

let hCivetConfig: (CompileOptions | undefined) = undef

// ---------------------------------------------------------------------------
// ASYNC

const getCivetConfig = async (
		hExtra: CompileOptions = {}
		): AutoPromise<CompileOptions> => {

	if (defined(hCivetConfig)) {
		return Object.assign(hCivetConfig, hExtra)
	}
	const path = await findInDir(process.cwd())
	assert(defined(path), "No civet config file found")
	hCivetConfig = await loadConfig(path)
	return Object.assign(hCivetConfig, hExtra)
}

// ---------------------------------------------------------------------------
// ASYNC

export const civet2ts = async (
		civetCode: string,
		hOptions: hash = {}
		): AutoPromise<string> => {

	type opt = {
		inlineMap: boolean
		}
	const {inlineMap} = getOptions<opt>(hOptions, {
		inlineMap: true
		})
	const hConfig = await getCivetConfig({inlineMap})
	return await compile(civetCode, hConfig)
}

// ---------------------------------------------------------------------------
// ASYNC

export const civet2tsFile = async (
		civetPath: string,
		tsPath: string = withExt(civetPath, '.ts'),
		hOptions: hash = {}
		): AutoPromise<string> => {   // --- returns tsPath or '' on error

	type opt = {
		inlineMap: boolean
		force: boolean
		nocheck: boolean
		}
	const {inlineMap, force, nocheck} = getOptions(hOptions, {
		inlineMap: true,
		force: false,
		nocheck: false
		})

	const civetCode = await Deno.readTextFile(civetPath)
	const tsCode = await civet2ts(civetCode, hOptions)
	await Deno.writeTextFile(tsPath, tsCode)
	if (!nocheck) {
		const errMsg = await typeCheckTsFile(tsPath)
		if (errMsg) {
			// --- touch the civet file so it will
			//     be compiled the next time
			await touch(civetPath)
			return ''
		}
	}
	return tsPath
}

// ---------------------------------------------------------------------------
// ASYNC

export const civet2js = async (
		civetCode: string,
		hOptions: hash = {}
		): AutoPromise<string> => {

	type opt = {
		inlineMap: boolean
		}
	const {inlineMap} = getOptions<opt>(hOptions, {
		inlineMap: false
		})
	try {
		const hConfig = await getCivetConfig({inlineMap})
		assert(defined(hConfig.parseOptions), "Bad config file")
		hConfig.js = true
		const jsCode = await compile(civetCode, hConfig)
		return jsCode
	}
	catch (err) {
		ERR(getErrStr(err))
		throw err
	}
}

// ---------------------------------------------------------------------------
//    from original civet.lib.civet
// ---------------------------------------------------------------------------

export type TCivetOptions = {
	force?: boolean
	nocheck?: boolean
	inlineMap?: boolean
	output?: string       // --- passed after -o option
	}

// ---------------------------------------------------------------------------
// ASYNC

export const civet2ast = async (civetCode: string): AutoPromise<Node> => {

	const tsCode = await civet2ts(civetCode)
	return ts2ast(tsCode)
}

// ---------------------------------------------------------------------------

// --- template literals to simplify displaying
//     the analysis of civet code

export const a = async (lStrings: TemplateStringsArray): AutoPromise<string> => {
	const tsCode = await civet2ts(lStrings[0], {nocheck: true})
	const result = analyzeTsCode(tsCode).asString()
	return result
}

export const A = async (lStrings: TemplateStringsArray): AutoPromise<string> => {
	const tsCode = await civet2ts(lStrings[0], {nocheck: true})
	const result = analyzeTsCode(tsCode, {dump: true}).asString()
	return result
}

// ---------------------------------------------------------------------------

class CCivetCompiler extends CFileHandler {

	get op() {
		return 'doCompileCivet'
	}

	// ..........................................................

	async canHandle(
			path: string,
			hOptions: hash = {}
			) {
		return (fileExt(path) === '.civet')
	}

	// ..........................................................

	override async needed(
			path: string,
			hOptions: hash = {}
			): AutoPromise<boolean> {

		return toBool(hOptions.force) || !newerDestFileExists(path, '.ts')
	}

	// ..........................................................

	getOutPath(
			path: string,
			output: string   // --- '.ts' or actual file name
			): string {

		assert((fileExt(path) === '.civet'), "Not a civet file")
		if (output === '.ts') {
			return withExt(path, '.ts')
		}
		else if (isFullPath(output)) {
			croak("output can't be a full path")
		}
		else {
			assert((fileExt(output) === '.ts'), "output must have .ts ext")
			return inSameDir(path, output)
		}
		return ''
	}

	// ..........................................................
	// ASYNC

	override async handle(
			path: string,
			hOptions: hash = {}
			): AutoPromise<TExecResult> {

		const {force, nocheck, output, inlineMap,
			} = getOptions<TCivetOptions>(hOptions, {
				force: false,
				nocheck: false,
				output: '.ts',
				inlineMap: true
				})

		assert((fileExt(path) === '.civet'), `Not a civet file: ${path}`)
		const tsPath = withExt(path, '.ts')
		try {
			const outPath = await civet2tsFile(path, tsPath, {
				inlineMap,
				force,
				nocheck
				})
			assert((outPath === tsPath), `Bad output file: '${outPath}'`)
			return {
				success: true,
				infile: path,
				outfile: outPath
				}
		}
		catch (err) {
			const errMsg = getErrStr(err)
			DBG(errMsg)
			return {
				success: false,
				stderr: `COMPILE FAILED: ${pathStr(path)} - ${errMsg}`
				}
		}
	}
}

export const doCompileCivet = new CCivetCompiler()

